  # access token in its subprotocol list (a browser can set no\n                # Authorization header on a WebSocket); Caddy redacts\n                # Authorization by itself but not this header.\n                request>headers>Sec-Websocket-Protocol delete\n            }\n'), ('        respond 404\n    }\n\n    handle /api/* {\n        reverse_proxy web:8000 {\n', "        respond 404\n    }\n\n    # ARCH48-S1:ws-live-review. The live review channel is a WebSocket\n    # (/api/v1/workspaces/{id}/review/collab/live). reverse_proxy passes the\n    # Upgrade through by itself; what this block adds is lifetime: frames are\n    # flushed as they arrive, and a config reload lets open reviewers' sockets\n    # run on for up to five minutes instead of cutting every one of them at\n    # once (they reconnect by themselves either way).\n    @review_live path /api/v1/workspaces/*/review/collab/live\n    handle @review_live {\n        reverse_proxy web:8000 {\n            header_up X-Forwarded-Proto {scheme}\n            header_up X-Real-IP {remote_host}\n            flush_interval -1\n            stream_close_delay 5m\n        }\n    }\n\n    handle /api/* {\n        reverse_proxy web:8000 {\n"))),),
